typedef void (*EventCallback)(int);

void handle_conn(int id) {}
void handle_disc(int id) {}
void handle_error(int id) {}

#define MAX_EVENTS 3

// Array of function pointers (Dispatch Table)
EventCallback EventDispatch[MAX_EVENTS] = {
    handle_conn,
    handle_disc,
    handle_error
};

enum EventID { CONN, DISC, ERROR };

// Usage: Dynamic invocation based on index
EventID current = DISC;
int payload = 42;

// Executes handle_disc(42)
EventDispatch[current](payload);

// Raw syntax alternative (less readable):
void (**raw_ptr_array)(int);
// ... initialization ...
raw_ptr_array[0](0);
